#!/usr/bin/env node
// tokens.json → theme.css (shadcn vars for panel + cards), ../../themes/shadcn_ui.yaml (HA theme),
// and ../../themes/custom-sidebar/custom-sidebar-config.yaml (elchininet/custom-sidebar styling).
// `--check` fails if generated files are out of date (used in CI).
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const t = JSON.parse(readFileSync(resolve(here, "tokens.json"), "utf8"));
const check = process.argv.includes("--check");

const vars = (o) => Object.entries(o).map(([k, v]) => `  --${k}: ${v};`).join("\n");

const css = `/* GENERATED by packages/tokens/build.mjs from tokens.json — do not edit by hand. */
:root, :host {
  --radius: ${t.radius};
  --font-sans: ${t.font};
${vars(t.light)}
}

.dark, :host([dark]) {
${vars(t.dark)}
}
`;

// Home Assistant theme: maps the same tokens onto HA's theme variables so stock screens
// (settings, more-info, the eveus/deye views until they are redone) match the new UI.
// Also exports `--hsu-*` custom properties consumed by custom-sidebar so light/dark mode
// switches automatically via HA's theme without reloading custom-sidebar-config.yaml.
const radiusPx = `${Math.round(parseFloat(t.radius) * 16)}px`;
const ha = (p) => ({
  "primary-color": p.primary,
  "accent-color": p.info,
  "primary-background-color": p.background,
  "secondary-background-color": p.muted,
  "card-background-color": p.card,
  "ha-card-background": p.card,
  "ha-card-border-color": p.border,
  "ha-card-border-width": "1px",
  "ha-card-border-radius": radiusPx,
  "ha-card-box-shadow": "none",
  "primary-text-color": p.foreground,
  "secondary-text-color": p["muted-foreground"],
  "disabled-text-color": p["muted-foreground"],
  "divider-color": p.border,
  "app-header-background-color": p.background,
  "app-header-text-color": p.foreground,
  "sidebar-background-color": p.card,
  "sidebar-icon-color": p["muted-foreground"],
  "sidebar-text-color": p["card-foreground"],
  "sidebar-selected-text-color": p["accent-foreground"],
  "sidebar-selected-icon-color": p["accent-foreground"],
  "light-primary-color": p.accent,
  "text-light-primary-color": p["accent-foreground"],
  "state-icon-color": p["muted-foreground"],
  "state-active-color": p.energy,
  "error-color": p.destructive,
  "warning-color": p.warning,
  "success-color": p.success,
  "info-color": p.info,
  "switch-checked-color": p.primary,
  "switch-checked-button-color": p["primary-foreground"],
  "switch-checked-track-color": p.primary,
  "input-fill-color": p.card,
  "mdc-theme-primary": p.primary,
  "hsu-sidebar-bg": p.card,
  "hsu-sidebar-fg": p["card-foreground"],
  "hsu-sidebar-muted": p["muted-foreground"],
  "hsu-sidebar-active-bg": p.accent,
  "hsu-sidebar-active-fg": p["accent-foreground"],
  "hsu-sidebar-border": p.border,
  "hsu-sidebar-badge-bg": p.primary,
  "hsu-sidebar-badge-fg": p["primary-foreground"],
  "hsu-sidebar-ring": p.ring,
  "hsu-radius": t.radius,
  "hsu-font": t.font,
});
const yamlScalar = (v) => (v.includes('"') ? `'${v.replace(/'/g, "''")}'` : `"${v}"`);
const yamlBlock = (o, indent) =>
  Object.entries(o)
    .map(([k, v]) => `${" ".repeat(indent)}${k}: ${yamlScalar(v)}`)
    .join("\n");

const yaml = `# GENERATED by packages/tokens/build.mjs from tokens.json — do not edit by hand.
# Install: copy to /config/themes/ (frontend: themes: !include_dir_merge_named themes), then
# Developer tools → Actions → frontend.reload_themes, and pick "shadcn_ui" in your profile.
shadcn_ui:
  font-family: '${t.font}'
  modes:
    light:
${yamlBlock(ha(t.light), 6)}
    dark:
${yamlBlock(ha(t.dark), 6)}
`;

// elchininet/custom-sidebar (v17+) config: consumes `--hsu-*` theme variables from shadcn_ui.yaml
// so light/dark mode switches cleanly via HA's profile theme without editing this file.
// Item ordering/visibility is intentionally left to HA's built-in sidebar editor.
const sidebarConfig = `# GENERATED by packages/tokens/build.mjs from tokens.json — do not edit by hand.
#
# Plugin: elchininet/custom-sidebar (v17.0.0+ required for Home Assistant 2026.8+)
# Docs:   https://elchininet.github.io/custom-sidebar/
# Tested: Home Assistant 2026.11.3 (frontend 20261028.8)
#
# Install:
#   1. Install "Custom Sidebar" via Settings → Marketplace (HA 2026.11+) or HACS.
#   2. Add to configuration.yaml and restart HA:
#        frontend:
#          extra_module_url:
#            - /local/community/custom-sidebar/custom-sidebar-plugin.js   # Marketplace (HA 2026.11+)
#            # - /hacsfiles/custom-sidebar/custom-sidebar-plugin.js       # HACS (HA < 2026.11)
#   3. Copy this file to /config/www/custom-sidebar-config.yaml (or run \`pnpm deploy:ha --theme\`).
#   4. Select theme "shadcn_ui" in your HA profile and refresh the page.
#
# Selectors verified on HA 2026.11.3 (home-assistant → home-assistant-main → ha-sidebar):
#   :host([expanded]) / :host([narrow])       — expanded desktop/drawer vs collapsed icon rail
#   .menu / .menu .title                      — top sidebar header bar and title
#   ha-list-nav / ha-list-nav.after-spacer    — top scrollable list and fixed bottom section
#   ha-list-item-button / .selected / .user   — navigation rows, active state, bottom profile row
#   ha-svg-icon[slot="start"], ha-icon[slot="start"] — leading item icons
#   .item-text / .badge[slot="start"|"end"]   — row label and notification/update count badges

# Colors read from shadcn_ui theme variables (--hsu-*) — auto-switch between light and dark modes
sidebar_background: "var(--hsu-sidebar-bg, var(--sidebar-background-color))"
sidebar_border_color: "var(--hsu-sidebar-border, var(--divider-color))"
menu_background: "var(--hsu-sidebar-bg, var(--sidebar-background-color))"
title_color: "var(--hsu-sidebar-fg, var(--sidebar-text-color))"
sidebar_button_color: "var(--hsu-sidebar-muted, var(--sidebar-icon-color))"
sidebar_button_color_hover: "var(--hsu-sidebar-fg, var(--sidebar-text-color))"
sidebar_button_background_hover: "var(--hsu-sidebar-active-bg, rgba(128, 128, 128, 0.14))"
sidebar_button_background_hover_opacity: 1
text_color: "var(--hsu-sidebar-fg, var(--sidebar-text-color))"
text_color_selected: "var(--hsu-sidebar-active-fg, var(--sidebar-selected-text-color))"
text_color_hover: "var(--hsu-sidebar-fg, var(--sidebar-text-color))"
icon_color: "var(--hsu-sidebar-muted, var(--sidebar-icon-color))"
icon_color_selected: "var(--hsu-sidebar-active-fg, var(--sidebar-selected-icon-color))"
icon_color_hover: "var(--hsu-sidebar-fg, var(--sidebar-text-color))"
item_background_hover: "var(--hsu-sidebar-active-bg, rgba(128, 128, 128, 0.14))"
item_background_hover_opacity: 0.65
selection_background: "var(--hsu-sidebar-active-bg, rgba(128, 128, 128, 0.16))"
selection_opacity: 1
divider_color: "var(--hsu-sidebar-border, var(--divider-color))"
notification_color: "var(--hsu-sidebar-badge-bg, var(--accent-color))"
notification_text_color: "var(--hsu-sidebar-badge-fg, var(--text-accent-color, var(--text-primary-color)))"
notification_color_selected: "var(--hsu-sidebar-badge-bg, var(--accent-color))"
notification_text_color_selected: "var(--hsu-sidebar-badge-fg, var(--text-accent-color, var(--text-primary-color)))"
notification_color_hover: "var(--hsu-sidebar-badge-bg, var(--accent-color))"
notification_text_color_hover: "var(--hsu-sidebar-badge-fg, var(--text-accent-color, var(--text-primary-color)))"
scrollbar_thumb_color: "var(--hsu-sidebar-border, var(--scrollbar-thumb-color))"

# Item order and visibility are intentionally NOT generated from design tokens.
# Reorder or hide items using HA's built-in sidebar editor (long-press the sidebar title or
# Profile → Edit sidebar), or maintain a local copy with an \`order:\` section if you need
# per-user / per-device rules.
#
# order:
#   - item: "Дім"
#     order: 1

styles: |
  :host {
    font-family: var(--hsu-font, inherit);
    -webkit-font-smoothing: antialiased;
  }

  /* Header */
  .menu {
    border-bottom: 1px solid var(--hsu-sidebar-border, var(--divider-color));
  }
  .menu .title {
    font-family: var(--hsu-font, inherit);
    font-size: 0.9375rem;
    font-weight: 600;
    letter-spacing: -0.015em;
  }

  /* Navigation lists & footer separator */
  ha-list-nav {
    margin-block: 6px;
  }
  ha-list-nav.after-spacer {
    border-top: 1px solid var(--hsu-sidebar-border, var(--divider-color));
    margin-top: 0;
    padding-top: 6px;
  }

  /* Soft pill items — collapsed rail keeps 48px width centered inside 56px sidebar */
  ha-list-item-button {
    margin: 0 4px 2px;
    border-radius: var(--hsu-radius, 0.75rem);
    --ha-list-item-focus-radius: var(--hsu-radius, 0.75rem);
    --ha-color-focus: var(--hsu-sidebar-ring, var(--primary-color));
    --ha-row-item-min-height: 40px;
    --ha-row-item-gap: 10px;
    --ha-row-item-padding-inline: 12px;
  }
  :host ha-list-item-button:not(.selected)::before,
  :host ha-list-item-button.selected::before {
    border-radius: var(--hsu-radius, 0.75rem);
  }

  /* Expanded desktop & mobile drawer — full-width pills with 8px side inset */
  :host([expanded]) :is(ha-list-item-base, ha-list-item-button) {
    margin: 0 8px 2px;
    width: calc(100% - 16px) !important;
    --ha-row-item-min-height: 36px;
    --ha-row-item-padding-inline: 10px;
  }
  :host([narrow][expanded]) :is(ha-list-item-base, ha-list-item-button) {
    --ha-row-item-min-height: 40px;
  }

  /* Leading icons: crisp 18px visual weight centered inside 24px slot */
  ha-list-item-button > :is(ha-svg-icon, ha-icon)[slot="start"] {
    --mdc-icon-size: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: color 120ms ease;
  }

  /* Typography: shadcn text-sm, regular default / medium when selected */
  :host ha-list-item-button .item-text {
    font-family: var(--hsu-font);
    font-size: 0.875rem;
    font-weight: 400;
    letter-spacing: -0.006em;
  }
  :host ha-list-item-button.selected .item-text {
    font-weight: 500;
  }

  /* Notification & update count badges */
  :host ha-list-item-button > .badge {
    font-family: var(--hsu-font);
    font-variant-numeric: tabular-nums;
    font-weight: 600;
    border-radius: 999px;
    box-sizing: border-box;
  }
  :host ha-list-item-button > .badge[slot="end"] {
    min-width: 20px;
    height: 20px;
    padding: 0 6px;
    font-size: 11px;
    line-height: 20px;
  }
  :host(:not([expanded])) ha-list-item-button > .badge[slot="start"] {
    min-width: 16px;
    max-width: 24px;
    height: 16px;
    padding: 0 4px;
    font-size: 10px;
    line-height: 16px;
  }

  /* Profile item: avatar centered in collapsed rail & aligned to icon axis when expanded */
  ha-list-item-button.user {
    --ha-row-item-min-height: 40px;
    --ha-row-item-padding-inline: 8px 0;
  }
  :host([expanded]) ha-list-item-button.user {
    --ha-row-item-min-height: 40px;
    --ha-row-item-padding-inline: 8px 10px;
    --ha-row-item-gap: 8px;
  }
  :host([expanded]) ha-list-item-button.user ha-user-badge {
    width: 28px;
    height: 28px;
  }
`;

const outputs = [
  [resolve(here, "theme.css"), css],
  [resolve(here, "../../themes/shadcn_ui.yaml"), yaml],
  [resolve(here, "../../themes/custom-sidebar/custom-sidebar-config.yaml"), sidebarConfig],
];

let stale = false;
for (const [file, content] of outputs) {
  if (check) {
    if (!existsSync(file) || readFileSync(file, "utf8") !== content) {
      console.error(`stale: ${file} — run \`pnpm theme\``);
      stale = true;
    }
  } else {
    mkdirSync(dirname(file), { recursive: true });
    writeFileSync(file, content);
    console.log(`wrote ${file}`);
  }
}
if (stale) process.exit(1);
